class Service(_EmailExchangeV1EmailExchangeExchangeServiceWithIAM, ServiceRef):
    """A service, loaded."""

    @classmethod
    def _from(
        cls,
        session: _Session,
        scope: _Key,
        data: _EmailExchangeV1EmailExchangeExchangeServiceWithIAM,
    ) -> Self:
        ref_key: _Key = {**scope}
        ref_key["exchangeService"] = scope.get("exchangeService") or None
        return _bind(cls, session, data, ref_key)


class ServiceCollection(_Collection[Service]):
    """Every service: iterate, `filter`, or call with an identifier."""

    def __call__(self, exchange_service: str, /) -> ServiceRef:
        ref_key: _Key = {
            **self._scope,
            "exchangeService": _identifier(exchange_service),
        }
        return ServiceRef._of(self._session, ref_key)

    def filter(
        self,
        *,
        iam_tags: dict[str, list[EmailExchangeIamResourceTagFilter]] | None = None,
    ) -> ServiceCollection:
        """The same collection, narrowed to the items matching these criteria."""
        return self._narrowed(iam_tags=iam_tags)

    async def _items(self) -> AsyncIterator[Service]:
        listed = await self._session.api(_EmailExchangeV1API).list_service(
            organization_name=_required(self._scope, "organizationName"),
            **{k: v for k, v in self._criteria.items() if k not in {"_"}},
        )
        scope: _Key = {
            **self._scope,
        }
        refs = [
            ServiceRef._of(self._session, {**scope, "exchangeService": str(value)})
            for value in listed
        ]
        async for loaded in _load_each(
            refs, self._session.client.settings.max_concurrency
        ):
            yield loaded

    async def ids(self) -> AsyncIterator[str]:
        """The identifiers only, without loading the objects."""
        for value in await self._session.api(_EmailExchangeV1API).list_service(
            organization_name=_required(self._scope, "organizationName"),
            **{k: v for k, v in self._criteria.items() if k not in {"_"}},
        ):
            yield str(value)


